layer.css:
[data-ryt="pitch"] { color: rgb(204, 255, 182); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 700; font-style: normal; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(204, 255, 182); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7px; padding-right: 10px; padding-bottom: 7px; padding-left: 10px; transition: all }
[data-ryt="footer"] { color: var(--ryt-muted); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-text); background-image: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 0) 5px, var(--ryt-text) 5px, var(--ryt-text)); background-size: 100% 6px; background-position: 50% 100%; background-repeat: repeat-x; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: var(--ryt-accent); font-family: var(--ryt-font-heading); font-size: 21px; font-weight: 700; font-style: normal; line-height: 1.25; letter-spacing: 0.21px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24px; font-weight: 700; font-style: normal; line-height: 1.333; letter-spacing: 0.24px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-accent); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 12.8px; font-weight: 200; font-style: normal; line-height: 1.172; letter-spacing: 0.128px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); background-image: linear-gradient(rgba(0, 0, 0, 0), rgba(0, 0, 0, 0) 5px, var(--ryt-text) 5px, var(--ryt-text)); background-size: 100% 6px; background-position: 50% 100%; background-repeat: repeat-x; border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.725; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { background-image: linear-gradient(transparent, transparent 4px, rgb(212, 128, 170) 4px, rgb(212, 128, 170)) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { background-image: linear-gradient(transparent, transparent 4px, rgb(212, 128, 170) 4px, rgb(212, 128, 170)) }
[data-ryt="nav"] a:hover { background-image: linear-gradient(transparent, transparent 4px, rgb(212, 128, 170) 4px, rgb(212, 128, 170)); background-image: linear-gradient(transparent, transparent 5px, var(--ryt-accent) 5px, var(--ryt-accent)) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { background-image: linear-gradient(transparent, transparent 4px, rgb(212, 128, 170) 4px, rgb(212, 128, 170)) }
[data-ryt="pitch"]::before { content: "“"; display: inline; margin-right: 7px; vertical-align: -11.2px; color: rgb(204, 255, 182); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 28px; font-weight: 700; font-style: normal; line-height: 0.1; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(204, 255, 182); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: rgb(204, 255, 182) }
